// ============================================================
// Return 交易日狀態（子流程「台股: 取得交易日狀態」的最後一個節點）
// 用途：根據證交所休市日清單，回答「今天是不是交易日」，並附上相關資訊。
// 輸出欄位：
//   ok               休市日資料是否查詢成功
//   date / dateLabel 今天的日期（2026-09-29 / 2026/09/29（週二））
//   isWeekend        是否為週末
//   isTradingDay     是否為交易日
//   closedReason     休市原因（交易日為空字串）
//   specialNote      特殊交易日提示（開紅盤、封關日）
//   nextTradingDate / nextTradingLabel  下一個交易日
//   breakNotice      連假休市預告（只有「明天開始連假且含平日休市」才有）
//   error            查詢失敗時的說明
// ============================================================

const TZ = 'Asia/Taipei';
// 星期對照：Luxon 的 weekday 是 1（週一）到 7（週日），陣列從 0 開始，所以用 weekday - 1 取值
const WEEK = ['一', '二', '三', '四', '五', '六', '日'];

// 讀取呼叫時傳入的 date 參數；沒傳（空字串）就代表「今天」。測試時可傳入任意日期
const inputDate = String($('Start').first().json.date || '').trim();
// DateTime 是 n8n 內建的 Luxon 日期工具；fromISO 把 2026-09-29 這種文字轉成日期
let today = inputDate ? DateTime.fromISO(inputDate, { zone: TZ }) : $now.setZone(TZ);
if (!today.isValid) today = $now.setZone(TZ);             // 傳入的日期格式錯誤時，改用今天
today = today.startOf('day');                             // 時間歸零到當天 00:00，方便日期比較

// 證交所 API 回傳的清單：只保留有日期（Date）和名稱（Name）的資料
// map 轉換每一筆、filter 篩選符合條件的資料
const rows = $input.all().map(i => i.json).filter(r => r && r.Date && r.Name);
// 有資料才算查詢成功；API 失敗時前一個節點會傳來空資料或錯誤訊息
const apiOk = rows.length > 0;

// 三個日期格式化的小工具（箭頭函式：d 是輸入的日期，=> 右邊是回傳值）
const toISO = d => d.toFormat('yyyy-LL-dd');                                   // 2026-09-29
const label = d => `${d.toFormat('yyyy/LL/dd')}（週${WEEK[d.weekday - 1]}）`;  // 2026/09/29（週二）
const short = d => `${d.month}/${d.day}（${WEEK[d.weekday - 1]}）`;             // 9/29（二）

// 證交所清單同時包含休市日與特殊交易日（開始交易日／最後交易日），日期為民國年 YYYMMDD
// closed：休市日（日期 → 原因）；special：有開盤的特殊交易日（日期 → 名稱）
const closed = new Map();
const special = new Map();
for (const r of rows) {
  const s = String(r.Date).trim();
  if (!/^\d{7}$/.test(s)) continue;                       // 不是 7 位數字（例如 1150928）就跳過
  // 民國年轉西元：115 + 1911 = 2026，組成 2026-09-28
  const iso = `${1911 + parseInt(s.slice(0, 3), 10)}-${s.slice(3, 5)}-${s.slice(5, 7)}`;
  // 名稱中斜線前後的空白統一去掉，例如「孔子誕辰紀念日 / 教師節」→「孔子誕辰紀念日/教師節」
  const name = String(r.Name).trim().replace(/\s*\/\s*/g, '/');
  // 名稱含「開始交易」或「最後交易」→ 有開盤的特殊交易日；其他都是休市日
  if (/開始交易|最後交易/.test(name)) special.set(iso, name);
  // 「市場無交易，僅辦理結算交割作業」這類名稱太長，改成簡短的「封關期間無交易」
  else closed.set(iso, name.includes('無交易') ? '封關期間無交易' : name);
}

// 週末：weekday 6 = 週六、7 = 週日
const isWeekend = d => d.weekday >= 6;
// 有開盤 = 不是週末，而且不在休市日清單裡
const isOpen = d => !isWeekend(d) && !closed.has(toISO(d));

// 從明天開始一天一天往後找，找到第一個有開盤的日子（最多找 60 天，避免無限迴圈）
let next = today.plus({ days: 1 });
for (let i = 0; i < 60 && !isOpen(next); i++) next = next.plus({ days: 1 });

const tIso = toISO(today);
const todayOpen = isOpen(today);

// 休市預告：今天有開盤、而且查詢成功時才計算
let breakNotice = '';
if (todayOpen && apiOk) {
  const start = today.plus({ days: 1 });                  // 從明天開始算
  const days = Math.round(next.diff(start, 'days').days); // 明天到下一個交易日之間，共休市幾天
  const reasons = [];                                     // 收集休市原因（不重複）
  let hasWeekdayHoliday = false;                          // 這段期間是否包含「平日」的休市日
  for (let i = 0; i < days; i++) {
    const d = start.plus({ days: i });
    const iso = toISO(d);
    if (closed.has(iso) && !isWeekend(d)) hasWeekdayHoliday = true;
    const reason = closed.get(iso) || (isWeekend(d) ? '週末' : '');
    if (reason && !reasons.includes(reason)) reasons.push(reason);
  }
  // 只有一般週末（沒有平日休市）就不預告，避免每個週五都推一次
  if (hasWeekdayHoliday) {
    const end = next.minus({ days: 1 });                  // 連假最後一天 = 下一個交易日的前一天
    const range = days === 1 ? short(start) : `${short(start)}～${short(end)}`;
    breakNotice = `📅 休市預告：${range}休市 ${days} 天（${reasons.join('、')}），${short(next)}恢復交易`;
  }
}

// 今天如果是特殊交易日，加上白話的補充說明
let specialNote = special.get(tIso) || '';
if (specialNote.includes('春節後開始交易')) specialNote += '（開紅盤）';
if (specialNote.includes('春節前最後交易')) specialNote += '（封關日）';

// 回傳給呼叫這個子流程的節點（B-、C-、D- 開頭的「取得交易日狀態」）
return [{
  json: {
    ok: apiOk,
    date: tIso,
    dateLabel: label(today),
    isWeekend: isWeekend(today),
    isTradingDay: todayOpen,
    closedReason: todayOpen ? '' : (closed.get(tIso) || '週末'),
    specialNote: specialNote ? `今日為${specialNote}` : '',
    nextTradingDate: toISO(next),
    nextTradingLabel: label(next),
    breakNotice,
    error: apiOk ? '' : '無法取得證交所休市日資料，僅依週末判斷'
  }
}];
